const brl = n => 'R$ ' + Number(n).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const pad = n => String(n).padStart(2, '0');
const brt = d => new Date(new Date(d).getTime() - 3 * 3600 * 1000); // America/Sao_Paulo (UTC-3, sem horario de verao)
const dataBR = d => { const x = brt(d); return pad(x.getUTCDate()) + '/' + pad(x.getUTCMonth() + 1) + '/' + x.getUTCFullYear(); };
const horaBR = d => { const x = brt(d); return pad(x.getUTCHours()) + ':' + pad(x.getUTCMinutes()); };

const sd = $getWorkflowStaticData('global');
const enviados = sd.enviados_pedidos || [];
const novos = $input.all().map(i => i.json).filter(p => p && p.id && !enviados.includes(p.id));
return novos.map(p => ({ json: {
  pedido_id: p.id,
  payload: {
    evento: 'novo_pedido',
    pedido_numero: p.numero,
    status: p.status,
    cliente_nome: p.cliente_nome,
    cliente_telefone: p.cliente_telefone,
    valor_total: Number(p.valor_total),
    valor_total_formatado: brl(p.valor_total),
    data_criacao: p.created_at,
    data_criacao_formatada: dataBR(p.created_at) + ' ' + horaBR(p.created_at),
    origem: 'SmartLar - Supabase'
  }
}}));

const sd = $getWorkflowStaticData('global');
const ids = $input.all().map(i => i.json.pedido_id);
sd.enviados_pedidos = [...(sd.enviados_pedidos || []), ...ids].slice(-500);
return [{ json: { registrados_agora: ids.length, total_em_memoria: sd.enviados_pedidos.length } }];
